    // 画廊 16 张：8 张单图形（每种颜色两种形状 → 只差形状的困难负样本）+ 8 张双图形（含两对左右互换）
    const GALLERY = [[0], [2], [4], [3], [8], [7], [9], [11], [1, 6], [6, 1], [5, 10], [10, 5], [0, 2], [8, 3], [9, 8], [4, 9]];
    const scenesFrom = (list, seed) => { const r = LM.rng(seed); return list.map((cl) => sampleScene(r, cl.length === 1 ? { single: true, cls: cl[0] } : { single: false, cls: cl[0], cls2: cl[1] })); };
    const makeGallery = () => scenesFrom(GALLERY, 2025);
    /** zero-shot 测试集：每类 4 张单图形 = 48 张 */
    const makeZsTest = () => { const l = []; for (let k = 0; k < NCLS; k++) for (let i = 0; i < 4; i++) l.push([k]); return scenesFrom(l, 777); };
    /** LLaVA 测试集：画廊 16 张 + 随机 16 张单图形 + 16 张双图形 */
    const makeCapTest = () => { const r = LM.rng(4040), l = makeGallery(); for (let i = 0; i < 32; i++) l.push(sampleScene(r, { single: i < 16 })); return l; };
    const abbr = (sc) => sc.objs.map((o) => COLORS[o.c].name[0] + SHAPES[o.s][0]).join('|');   // 红圆、红方|蓝圆
    const TEMPLATES = [
        { id: 0, label: '一个{颜色}的{形状}', f: (c, s) => `一个${c}的${s}` },
        { id: 1, label: '{颜色}的{形状}', f: (c, s) => `${c}的${s}` },
        { id: 2, label: '{颜色}{形状}', f: (c, s) => `${c}${s}` },
    ];
    const prompts = (t) => Array.from({ length: NCLS }, (_, k) => TEMPLATES[t].f(COLORS[Math.floor(k / NS)].name, SHAPES[k % NS]));
    const HOLD = { none: null, gt_yc: new Set([5, 9]) };                                     // 留出组合：绿色三角形、黄色圆形
    const PAGE_SEED = 2;                                                                       // 页面默认种子（spec.seed）；所有训练种子都由它派生
    const CLIP_DEFAULT = { N: 8, tau: 0.05, lr: 3e-3, steps: 2000, hard: false, pSingle: 0.7 };
    const LLAVA_DEFAULT = { B: 4, lr: 3e-3, steps: 3000, layer: 0, pSingle: 0.5 };
    const clipRecipe = (seed, o) => Object.assign({}, CLIP_DEFAULT, { seed, dataSeed: 1234 + seed }, o);
    const llavaRecipe = (seed, o) => Object.assign({}, LLAVA_DEFAULT, { seed: 3 + seed, dataSeed: 4321 + seed }, o);
