    const exportParams = (params) => LM.gpt.exportWeights({ params });
    const loadParams = (params, b64) => LM.gpt.loadWeights({ params }, b64);
    const randomViT = () => createViT(CLIP_CFG.img, 99);                                       // LLaVA 对照组：同结构、随机初始化
    const bakedViT = () => { const v = createViT(CLIP_CFG.img, 1); if (typeof P07_W !== 'undefined' && P07_W) loadParams(v.params, P07_W.vit.b64); return v; };
