            const n = D.zs.length, Pe = TEMPLATES.map((t) => embedTexts(clip.txt, prompts(t.id)).emb.data.slice());
            const sims = Pe.map((P) => { const s = new Float32Array(n * NCLS); for (let i = 0; i < n; i++) for (let k = 0; k < NCLS; k++) s[i * NCLS + k] = dotRow(R._zsI, i, P, k, e); return s; });
