        if (chunk !== 3) return;
        let ex = 0, ex1 = 0, n1 = 0, a = 0, na = 0;
        D.capTest.forEach((s, i) => { const ok = R.caps[i] === s.caption; if (ok) ex++; if (s.single) { n1++; if (ok) ex1++; } const [p, q] = attrScore(s, R.caps[i]); a += p; na += q; });
        const n = D.capTest.length, rec = { it: R.tr.it, exact: ex / n, exact1: ex1 / n1, exact2: (ex - ex1) / (n - n1), attr: a / na };
