            code: {
                title: 'C++ · pca2 / sharedSpace', src: `
                // 2 维 PCA（与 JS 的 LM.pca2 相同）：在 d×d 协方差矩阵上做幂迭代，求前两个主轴（等价于对 X − mean 做 SVD、取 V 的前两列）；
                // 每个轴的符号固定为「绝对值最大的分量为正」。返回每行的 2 维坐标 pts[2i], pts[2i + 1] 与两个轴的解释方差比例
                struct PCA2 { std::vector<float> pts; float varRatio[2] = {0, 0}; };

                PCA2 pca2(const std::vector<float>& X, int n, int d) {
                    std::vector<double> mean, C, w;
                    mean.assign(d, 0.0);
                    C.assign(d * d, 0.0);
                    for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) mean[j] += X[i * d + j] / (double)n;
                    for (int i = 0; i < n; i++)
                        for (int a = 0; a < d; a++) {
                            double xa = X[i * d + a] - mean[a];
                            for (int b = 0; b < d; b++) C[a * d + b] += xa * (X[i * d + b] - mean[b]) / n;
                        }
                    double total = 0;
                    for (int a = 0; a < d; a++) total += C[a * d + a];                          // 总方差 = 协方差矩阵的迹
                    Rng r = makeRng(7);
                    std::vector<std::vector<double>> axes;
                    PCA2 out;
                    for (int k = 0; k < 2; k++) {
                        std::vector<double> v;
                        for (int j = 0; j < d; j++) v.push_back(uniform(r) - 0.5);
                        double lam = 0;
                        for (int it = 0; it < 120; it++) {
                            w.assign(d, 0.0);
                            for (int a = 0; a < d; a++) for (int b = 0; b < d; b++) w[a] += C[a * d + b] * v[b];   // w = C·v
                            for (const std::vector<double>& u : axes) {                         // 去掉已经求出的主轴方向
                                double p = 0;
                                for (int j = 0; j < d; j++) p += w[j] * u[j];
                                for (int j = 0; j < d; j++) w[j] -= p * u[j];
                            }
                            double nrm = 0;
                            for (int j = 0; j < d; j++) nrm += w[j] * w[j];
                            nrm = nrm > 0 ? std::sqrt(nrm) : 1;
                            lam = nrm;                                                          // 收敛后 ‖C·v‖ = 特征值（这个轴上的方差）
                            for (int j = 0; j < d; j++) v[j] = w[j] / nrm;
                        }
                        int bi = 0;
                        for (int j = 1; j < d; j++) if (std::fabs(v[j]) > std::fabs(v[bi])) bi = j;
                        if (v[bi] < 0) for (double& x : v) x = -x;
                        axes.push_back(v);
                        out.varRatio[k] = (float)(total > 0 ? lam / total : 0);
                    }
                    out.pts = floats(2 * n);
                    for (int i = 0; i < n; i++)
                        for (int k = 0; k < 2; k++) {
                            double s = 0;
                            for (int j = 0; j < d; j++) s += (X[i * d + j] - mean[j]) * axes[k][j];
                            out.pts[2 * i + k] = (float)s;
                        }
                    return out;
                }

                // 上图：画廊 n 张图与它们的 n 条 caption → 2n 个单位向量 X = [I_1 … I_n ; T_1 … T_n] 一起做 PCA
                // （第 i 张图 = 第 i 个点，第 i 条 caption = 第 n + i 个点；配对的两个点之间画虚线）
                PCA2 sharedSpace(const CLIP& clip, const std::vector<Scene>& scenes) {
                    Var I = embedImages(clip.img, scenes).emb, T = embedTexts(clip.txt, captionsOf(scenes)).emb;
                    std::vector<float> X = I->val.v;
                    X.insert(X.end(), T->val.v.begin(), T->val.v.end());
                    return pca2(X, 2 * (int)scenes.size(), I->val.cols);
                }`,
            },
